import Complex128Array = require( '@stdlib/array/complex128' );
import zleftPadCircular = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 12 );

	zleftPadCircular( x.length, 2, x, 1, y, 1 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 12 );

	zleftPadCircular( '10', 2, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( true, 2, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( false, 2, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( null, 2, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( undefined, 2, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( [], 2, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( {}, 2, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( ( x: number ): number => x, 2, x, 1, y, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 12 );

	zleftPadCircular( x.length, '10', x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, true, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, false, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, null, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, undefined, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, [], x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, {}, x, 1, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, ( x: number ): number => x, x, 1, y, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a Complex128Array...
{
	const y = new Complex128Array( 12 );

	zleftPadCircular( 10, 2, 10, 1, y, 1 ); // $ExpectError
	zleftPadCircular( 10, 2, true, 1, y, 1 ); // $ExpectError
	zleftPadCircular( 10, 2, false, 1, y, 1 ); // $ExpectError
	zleftPadCircular( 10, 2, null, 1, y, 1 ); // $ExpectError
	zleftPadCircular( 10, 2, undefined, 1, y, 1 ); // $ExpectError
	zleftPadCircular( 10, 2, {}, 1, y, 1 ); // $ExpectError
	zleftPadCircular( 10, 2, ( x: number ): number => x, 1, y, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 12 );

	zleftPadCircular( x.length, 2, x, '10', y, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, true, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, false, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, null, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, undefined, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, [], y, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, {}, y, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, ( x: number ): number => x, y, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a Complex128Array...
{
	const x = new Complex128Array( 10 );

	zleftPadCircular( x.length, 2, x, 1, 10, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, true, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, false, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, null, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, undefined, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, {}, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 12 );

	zleftPadCircular( x.length, 2, x, 1, y, '10' ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, y, true ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, y, false ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, y, null ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, y, undefined ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, y, [] ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, y, {} ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, y, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 12 );

	zleftPadCircular(); // $ExpectError
	zleftPadCircular( x.length ); // $ExpectError
	zleftPadCircular( x.length, 2 ); // $ExpectError
	zleftPadCircular( x.length, 2, x ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1 ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, y ); // $ExpectError
	zleftPadCircular( x.length, 2, x, 1, y, 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 12 );

	zleftPadCircular.ndarray( x.length, 2, x, 1, 0, y, 1, 0 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 12 );

	zleftPadCircular.ndarray( '10', 2, x, 1, 0, y, 1, 0 ); // $ExpectError
	zleftPadCircular.ndarray( true, 2, x, 1, 0, y, 1, 0 ); // $ExpectError
	zleftPadCircular.ndarray( false, 2, x, 1, 0, y, 1, 0 ); // $ExpectError
	zleftPadCircular.ndarray( null, 2, x, 1, 0, y, 1, 0 ); // $ExpectError
	zleftPadCircular.ndarray( undefined, 2, x, 1, 0, y, 1, 0 ); // $ExpectError
	zleftPadCircular.ndarray( [], 2, x, 1, 0, y, 1, 0 ); // $ExpectError
	zleftPadCircular.ndarray( {}, 2, x, 1, 0, y, 1, 0 ); // $ExpectError
	zleftPadCircular.ndarray( ( x: number ): number => x, 2, x, 1, 0, y, 1, 0 ); // $ExpectError
}

