	zleftPadCircular.ndarray(); // $ExpectError
	zleftPadCircular.ndarray( x.length ); // $ExpectError
	zleftPadCircular.ndarray( x.length, 2 ); // $ExpectError
	zleftPadCircular.ndarray( x.length, 2, x ); // $ExpectError
	zleftPadCircular.ndarray( x.length, 2, x, 1 ); // $ExpectError
	zleftPadCircular.ndarray( x.length, 2, x, 1, 0 ); // $ExpectError
	zleftPadCircular.ndarray( x.length, 2, x, 1, 0, y ); // $ExpectError
